function constructMaximumBinaryTree(nums) {
  // A decreasing stack: each new value adopts the last node it pops as its left child,
  // and becomes the right child of the larger node left on the stack.
  const stack = [];
  for (const value of nums) {
    const node = new TreeNode(value);
    let popped = null;
    while (stack.length > 0 && stack[stack.length - 1].val < value) popped = stack.pop();
    node.left = popped;
    if (stack.length > 0) stack[stack.length - 1].right = node;
    stack.push(node);
  }
  return stack[0];
}

