function generate(rand, size) {
  const pick = k => Math.floor(rand() * k);
  const n = size === 'large' ? 900 + pick(101) : 1 + pick(8);
  const limit = size === 'large' || rand() < 0.5 ? 1000 : 2 * n;
  // Draw n distinct values from 0..limit with a partial shuffle.
  const pool = Array.from({ length: limit + 1 }, (_, i) => i);
  for (let i = 0; i < n; i++) {
    const j = i + pick(pool.length - i);
    [pool[i], pool[j]] = [pool[j], pool[i]];
  }
  const nums = pool.slice(0, n);
  // Arrange them: random, ascending, descending, or rising then falling.
  const shape = pick(4);
  if (shape === 1) nums.sort((a, b) => a - b);
  if (shape === 2) nums.sort((a, b) => b - a);
  if (shape === 3) {
    nums.sort((a, b) => a - b);
    const rising = nums.filter((_, i) => i % 2 === 0);
    const falling = nums.filter((_, i) => i % 2 === 1).reverse();
    return [[...rising, ...falling]];
  }
  return [nums];
}
